  </p>
  <table>
    <thead>
      <tr><th>Period</th><th>Start Price</th><th>End Price</th><th>Years</th><th>CAGR</th><th>Total Return</th></tr>
    </thead>
    <tbody>
"""

sub_periods = [
    ("1972–2026 (Full)", rows[0], rows[-1]),
]
# Add decade-level periods
decades_list = ["1970s", "1980s", "1990s", "2000s", "2010s", "2020s"]
for dn in decades_list:
    if dn in decade_stats:
        ds = decade_stats[dn]
        sub_periods.append((dn, None, None))
        # We'll fill from decade_stats

for sp_name, sp_start, sp_end in sub_periods:
    if sp_start and sp_end:
        sy = (sp_end["date"] - sp_start["date"]).days / 365.25
        scagr = ((sp_end["close"] / sp_start["close"]) ** (1/sy) - 1) * 100
        sret = (sp_end["close"] / sp_start["close"] - 1) * 100
        html += f"""
        <tr>
          <td><strong>{sp_name}</strong></td>
          <td>${fmt(sp_start['close'], 2)}</td>
          <td>${fmt(sp_end['close'], 2)}</td>
          <td>{sy:.1f}</td>
          <td class="positive">{pct(scagr, 2)}</td>
          <td class="positive">{pct(sret, 0)}</td>
        </tr>"""

for dn in decades_list:
    if dn in decade_stats:
        ds = decade_stats[dn]
        cl = "positive" if ds["total_return"] >= 0 else "negative"
        html += f"""
        <tr>
          <td><strong>{dn}</strong></td>
          <td>${fmt(ds['start_price'], 2)}</td>
          <td>${fmt(ds['end_price'], 2)}</td>
          <td>~10</td>
          <td class="{cl}">{pct(ds['cagr'], 2)}</td>
          <td class="{cl}">{pct(ds['total_return'], 0)}</td>
        </tr>"""

html += f"""
    </tbody>
  </table>

  <div class="highlight-box" style="margin-top: 16px;">
    <h4>Record Levels</h4>
    <p><strong>All-Time High:</strong> ${fmt(ath, 2)} on {ath_date} &nbsp;|&nbsp;
    <strong>All-Time Low:</strong> ${fmt(all_time_low, 2)} on {atl_date} &nbsp;|&nbsp;
    <strong>Current ({latest_date_str}):</strong> ${fmt(latest_close, 2)}</p>
  </div>
</section>

