#!/usr/bin/env python3
"""Generate AXP Historical Stock Performance Report as self-contained HTML."""

import csv
import json
import math
from datetime import datetime
from collections import defaultdict

# ── Read data ──────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", "r") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            "date": datetime.fromisoformat(r["Date"]),
            "open": float(r["Open"]),
            "high": float(r["High"]),
            "low": float(r["Low"]),
            "close": float(r["Close"]),
            "volume": int(r["Volume"]),
            "dividends": float(r["Dividends"]),
            "splits": float(r["Stock Splits"]),
        })

rows.sort(key=lambda r: r["date"])
n = len(rows)

# ── Basic info ─────────────────────────────────────────────────────────────
first_date = rows[0]["date"]
last_date = rows[-1]["date"]
first_close = rows[0]["close"]
last_close = rows[-1]["close"]
total_days = n
total_years = (last_date - first_date).days / 365.25

# ── Daily returns ──────────────────────────────────────────────────────────
daily_returns = []
for i in range(1, n):
    if rows[i-1]["close"] > 0:
        r = (rows[i]["close"] - rows[i-1]["close"]) / rows[i-1]["close"]
        daily_returns.append(r)

# ── KPI 1: Cumulative Total Return ────────────────────────────────────────
cumulative_return_pct = (last_close / first_close - 1) * 100

# ── KPI 2: CAGR ───────────────────────────────────────────────────────────
cagr = (last_close / first_close) ** (1 / total_years) - 1
cagr_pct = cagr * 100

# ── KPI 3: Maximum Drawdown ───────────────────────────────────────────────
peak = rows[0]["close"]
max_drawdown = 0
max_dd_start = None
max_dd_end = None
current_peak = rows[0]["close"]
current_peak_idx = 0

for i, r in enumerate(rows):
    if r["close"] > current_peak:
        current_peak = r["close"]
        current_peak_idx = i
    dd = (current_peak - r["close"]) / current_peak
    if dd > max_drawdown:
        max_drawdown = dd
        max_dd_start = rows[current_peak_idx]["date"]
        max_dd_end = r["date"]

max_drawdown_pct = max_drawdown * 100

# ── KPI 4: Annualized Volatility ──────────────────────────────────────────
mean_ret = sum(daily_returns) / len(daily_returns)
variance = sum((r - mean_ret) ** 2 for r in daily_returns) / (len(daily_returns) - 1)
daily_vol = math.sqrt(variance)
annualized_vol = daily_vol * math.sqrt(252)
annualized_vol_pct = annualized_vol * 100

# ── KPI 5: Total Dividends ────────────────────────────────────────────────
total_dividends = sum(r["dividends"] for r in rows)
dividend_dates = [(r["date"], r["dividends"]) for r in rows if r["dividends"] > 0]
num_dividend_payments = len(dividend_dates)

# ── Split events ──────────────────────────────────────────────────────────
split_events = [(r["date"], r["splits"]) for r in rows if r["splits"] > 0]

# ── Yearly returns ────────────────────────────────────────────────────────
yearly = defaultdict(lambda: {"first": None, "last": None, "close": None})
for r in rows:
    y = r["date"].year
    if yearly[y]["first"] is None:
        yearly[y]["first"] = r["close"]
    yearly[y]["last"] = r["close"]
yearly_returns = {}
for y in sorted(yearly):
    f = yearly[y]["first"]
    l = yearly[y]["last"]
    if f > 0:
        yearly_returns[y] = ((l / f) - 1) * 100

# ── Decade analysis ───────────────────────────────────────────────────────
decade_map = {
    "1970s": (1970, 1979),
    "1980s": (1980, 1989),
    "1990s": (1990, 1999),
    "2000s": (2000, 2009),
    "2010s": (2010, 2019),
    "2020s": (2020, 2029),
}

decade_stats = {}
for dname, (start, end) in decade_map.items():
    d_rows = [r for r in rows if start <= r["date"].year <= end]
    if not d_rows:
        continue
    d_first = d_rows[0]["close"]
    d_last = d_rows[-1]["close"]
    d_return = ((d_last / d_first) - 1) * 100
    d_days = len(d_rows)
    d_years = (d_rows[-1]["date"] - d_rows[0]["date"]).days / 365.25
    d_cagr = ((d_last / d_first) ** (1 / max(d_years, 0.01)) - 1) * 100

    # Daily returns within decade
    d_rets = []
    for i in range(1, len(d_rows)):
        if d_rows[i-1]["close"] > 0:
            d_rets.append((d_rows[i]["close"] - d_rows[i-1]["close"]) / d_rows[i-1]["close"])
    d_mean = sum(d_rets) / max(len(d_rets), 1)
    d_var = sum((x - d_mean) ** 2 for x in d_rets) / max(len(d_rets) - 1, 1)
    d_vol = math.sqrt(max(d_var, 0)) * math.sqrt(252) * 100

    # Max drawdown in decade
    d_peak = d_rows[0]["close"]
    d_max_dd = 0
    for r in d_rows:
        if r["close"] > d_peak:
            d_peak = r["close"]
        dd = (d_peak - r["close"]) / d_peak
        if dd > d_max_dd:
            d_max_dd = dd

    # Dividends in decade
    d_divs = sum(r["dividends"] for r in d_rows)
    d_div_yield = (d_divs / d_first) * 100
    div_years = max(d_years, 0.01)
    d_avg_div_yield = d_div_yield / div_years

    decade_stats[dname] = {
        "start_price": round(d_first, 2),
        "end_price": round(d_last, 2),
        "total_return": round(d_return, 1),
        "cagr": round(d_cagr, 2),
        "volatility": round(d_vol, 2),
        "max_drawdown": round(d_max_dd * 100, 1),
        "dividends": round(d_divs, 2),
        "trading_days": d_days,
    }

# ── Bull/bear phases (≥20% moves) ─────────────────────────────────────────
phases = []
current_start_idx = 0
current_trough_idx = 0
looking_for_peak = True  # Start looking for troughs first (from peak)

# Find major drawdowns (≥20%) and subsequent recoveries
i = 0
while i < n:
    # Find a peak then the subsequent trough
    peak_idx = i
    peak_val = rows[peak_idx]["close"]
    trough_idx = peak_idx
    trough_val = peak_val

    # Look forward for a 20%+ decline
    for j in range(peak_idx + 1, n):
        if rows[j]["close"] < trough_val:
            trough_val = rows[j]["close"]
            trough_idx = j
        # If price recovers above peak before 20% decline, reset peak
        if rows[j]["close"] > peak_val:
            peak_idx = j
            peak_val = rows[j]["close"]
            trough_idx = j
            trough_val = peak_val
            continue
        # Check if we have a 20% decline
        dd = (peak_val - trough_val) / peak_val
        if dd >= 0.20:
            # Now find the recovery (when price surpasses the peak)
            recovery_idx = None
            for k in range(trough_idx + 1, n):
                if rows[k]["close"] >= peak_val:
                    recovery_idx = k
                    break
            phases.append({
                "type": "bear",
                "start": rows[peak_idx]["date"],
                "end": rows[trough_idx]["date"],
                "peak": round(peak_val, 2),
                "trough": round(trough_val, 2),
                "decline": round(dd * 100, 1),
                "recovery_date": rows[recovery_idx]["date"] if recovery_idx else None,
                "recovery_days": (recovery_idx - trough_idx) if recovery_idx else None,
            })
            i = trough_idx
            break
    else:
        i += 1
        continue
    i += 1

# Deduplicate overlapping phases
filtered_phases = []
for p in phases:
    # Keep only if decline >= 20% and not completely contained in another
    if p["decline"] < 20:
        continue
    filtered_phases.append(p)
phases = filtered_phases

# ── Monthly closing prices for the long-term chart ─────────────────────────
monthly = []
current_month = None
for r in rows:
    ym = (r["date"].year, r["date"].month)
    if ym != current_month:
        monthly.append({"date": r["date"].strftime("%Y-%m-%d"), "close": r["close"]})
        current_month = ym
if monthly[-1]["date"] != rows[-1]["date"].strftime("%Y-%m-%d"):
    monthly.append({"date": rows[-1]["date"].strftime("%Y-%m-%d"), "close": rows[-1]["close"]})

# ── Volume by year ────────────────────────────────────────────────────────
yearly_volume = defaultdict(lambda: {"total": 0, "count": 0, "max": 0})
for r in rows:
    y = r["date"].year
    yearly_volume[y]["total"] += r["volume"]
    yearly_volume[y]["count"] += 1
    yearly_volume[y]["max"] = max(yearly_volume[y]["max"], r["volume"])

# ── Dividends by year ─────────────────────────────────────────────────────
yearly_dividends = defaultdict(float)
for r in rows:
    yearly_dividends[r["date"].year] += r["dividends"]

# ── Rolling 3-year annualized return ──────────────────────────────────────
rolling_returns = []
for i in range(len(monthly)):
    target_date = datetime.strptime(monthly[i]["date"], "%Y-%m-%d")
    cutoff = target_date.replace(year=target_date.year - 3)
    # Find closest monthly close
    best = None
    for m in monthly:
        md = datetime.strptime(m["date"], "%Y-%m-%d")
        if md <= cutoff:
            best = m
    if best and best["close"] > 0:
        ann_ret = ((monthly[i]["close"] / best["close"]) ** (1/3) - 1) * 100
        rolling_returns.append({"date": monthly[i]["date"], "return": round(ann_ret, 2)})

# ── Build HTML ─────────────────────────────────────────────────────────────

def fmt(n, decimals=2):
    return f"{n:,.{decimals}f}"

def pct(n, decimals=1):
    return f"{n:,.{decimals}f}%"

# Price series as JSON for charts
close_series = [{"d": r["date"].strftime("%Y-%m-%d"), "c": r["close"]} for r in rows]
# Sampled for lighter DOM - use monthly for main chart
monthly_json = json.dumps(monthly)

# Yearly returns JSON
yearly_json = json.dumps([{"y": y, "r": round(yearly_returns.get(y, 0), 2)} for y in sorted(yearly)])

# Volume JSON (sampled monthly for performance)
vol_monthly = []
cm = None
vol_acc = 0
vol_cnt = 0
for r in rows:
    ym = (r["date"].year, r["date"].month)
    if ym != cm:
        if cm is not None:
            vol_monthly.append({"d": f"{cm[0]}-{cm[1]:02d}-01", "v": vol_acc, "avg": vol_acc // max(vol_cnt, 1)})
        cm = ym
        vol_acc = 0
        vol_cnt = 0
    vol_acc += r["volume"]
    vol_cnt += 1
if cm:
    vol_monthly.append({"d": f"{cm[0]}-{cm[1]:02d}-01", "v": vol_acc, "avg": vol_acc // max(vol_cnt, 1)})
vol_json = json.dumps(vol_monthly)

# Drawdown series
dd_series = []
peak_val = rows[0]["close"]
for r in rows:
    if r["close"] > peak_val:
        peak_val = r["close"]
    dd = (peak_val - r["close"]) / peak_val * 100
    dd_series.append({"d": r["date"].strftime("%Y-%m-%d"), "dd": round(dd, 2)})
dd_json = json.dumps(dd_series)

# Decade bar data
decade_bar = json.dumps([
    {"decade": d, "return": decade_stats[d]["total_return"], "cagr": decade_stats[d]["cagr"],
     "vol": decade_stats[d]["volatility"], "max_dd": decade_stats[d]["max_drawdown"]}
    for d in ["1970s", "1980s", "1990s", "2000s", "2010s", "2020s"] if d in decade_stats
])

# Dividend annual
div_annual = json.dumps([{"y": y, "d": round(yearly_dividends.get(y, 0), 4)} for y in sorted(yearly_dividends)])

# Split events JSON
splits_json = json.dumps([{"d": s[0].strftime("%Y-%m-%d"), "r": s[1]} for s in split_events])

# Rolling returns JSON
rolling_json = json.dumps(rolling_returns)

# Major events annotation
major_events = [
    {"date": "1973-10-01", "label": "1973 Oil Crisis"},
    {"date": "1987-10-19", "label": "Black Monday"},
    {"date": "2000-03-01", "label": "Dot-com Peak"},
    {"date": "2008-09-15", "label": "Lehman Collapse"},
    {"date": "2020-03-23", "label": "COVID-19 Low"},
]

# All-time high
ath = max(r["close"] for r in rows)
ath_date = [r for r in rows if r["close"] == ath][0]["date"].strftime("%Y-%m-%d")
all_time_low = min(r["close"] for r in rows)
atl_date = [r for r in rows if r["close"] == all_time_low][0]["date"].strftime("%Y-%m-%d")

# Latest metrics
latest_close = rows[-1]["close"]
latest_date_str = rows[-1]["date"].strftime("%B %d, %Y")

# Crash episodes detail
crash_episodes = [
    {"name": "2008 Global Financial Crisis", "start": "2007-10-09", "end": "2009-03-09"},
    {"name": "COVID-19 Crash", "start": "2020-02-19", "end": "2020-03-23"},
    {"name": "1987 Black Monday", "start": "1987-10-05", "end": "1987-12-04"},
    {"name": "Dot-com Bust", "start": "2000-03-27", "end": "2002-10-09"},
]

crash_details = []
for ep in crash_episodes:
    ep_start = datetime.strptime(ep["start"], "%Y-%m-%d")
    ep_end = datetime.strptime(ep["end"], "%Y-%m-%d")
    ep_rows = [r for r in rows if ep_start <= r["date"] <= ep_end]
    if ep_rows:
        p = max(r["close"] for r in ep_rows)
        t = min(r["close"] for r in ep_rows)
        ep_dd = (p - t) / p * 100
        crash_details.append({**ep, "peak": round(p, 2), "trough": round(t, 2), "drawdown": round(ep_dd, 1)})

# Current price vs ath
pct_from_ath = (latest_close / ath - 1) * 100

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
