        <tr><td>Average Annual Dividend (recent 5 years)</td><td><strong>${fmt(sum(yearly_dividends.get(y, 0) for y in range(2021, 2026)) / 5, 2)}</strong></td></tr>
      </table>
    </div>
    <div>
      <h3>Stock Split History</h3>
"""

if split_events:
    html += """
      <table>
        <thead><tr><th>Date</th><th>Split Ratio</th></tr></thead>
        <tbody>"""
    for sd, sr in split_events:
        html += f"""
          <tr><td>{sd.strftime('%B %d, %Y')}</td><td>{int(sr)}-for-1</td></tr>"""
    html += """
        </tbody>
      </table>"""
else:
    html += "<p>No stock splits recorded in this dataset (prices are split-adjusted).</p>"

html += """
    </div>
  </div>

  <div class="highlight-box" style="margin-top: 16px;">
    <h4>Income Profile for Long-Term Shareholders</h4>
    <p>AXP has maintained a consistent dividend program throughout its history, establishing it as a reliable
    income-generating holding. Dividend growth has been particularly strong since the 2000s, reflecting the
    company's transition to a capital-light, fee-based business model. The cumulative dividends paid over the
    full period represent a meaningful component of total shareholder return, especially when reinvested.</p>
  </div>
</section>

<!-- ═══════════ DECADE-BY-DECADE COMPARISON ═══════════ -->
<section id="decade-comparison">
  <h2>Decade-by-Decade Performance Comparison</h2>

  <div class="chart-container">
    <div id="chart-decade-return" class="chart"></div>
  </div>

  <div class="chart-container">
    <div id="chart-decade-risk" class="chart"></div>
  </div>

  <table>
    <thead>
      <tr>
        <th>Decade</th>
        <th>Start Price</th>
        <th>End Price</th>
        <th>Total Return</th>
        <th>CAGR</th>
        <th>Volatility</th>
        <th>Max Drawdown</th>
        <th>Dividends</th>
        <th>Trading Days</th>
      </tr>
    </thead>
    <tbody>
"""

for dn in ["1970s", "1980s", "1990s", "2000s", "2010s", "2020s"]:
    if dn not in decade_stats:
        continue
    ds = decade_stats[dn]
    cl_r = "positive" if ds["total_return"] >= 0 else "negative"
    cl_c = "positive" if ds["cagr"] >= 0 else "negative"
    html += f"""
      <tr>
        <td><strong>{dn}</strong></td>
        <td>${fmt(ds['start_price'], 2)}</td>
        <td>${fmt(ds['end_price'], 2)}</td>
