    fstr = content[idx:]
    # Count braces
    single_open = 0
    double_open = 0
    i = 0
    in_triple_quote = False
    lines = fstr.split('\n')
    for ln, line in enumerate(lines):
        # Count braces ignoring {{ and }}
        for j, ch in enumerate(line):
            if ch == '{':
                if j+1 < len(line) and line[j+1] == '{':
                    continue  # skip {{
                single_open += 1
            elif ch == '}':
                if j > 0 and line[j-1] == '}':
                    continue  # skip }}
                single_open -= 1
        if single_open != 0:
            # Find the mismatched line
            pass
    print(f'Final brace balance: {single_open}')

    # Print lines where balance changes significantly
    single_open = 0
    for ln, line in enumerate(lines):
        for j, ch in enumerate(line):
            if ch == '{':
                if j+1 < len(line) and line[j+1] == '{':
                    pass  # skip
                else:
                    single_open += 1
            elif ch == '}':
                if j > 0 and line[j-1] == '}':
                    pass  # skip
                else:
                    single_open -= 1
        if abs(single_open) > 3:
            print(f'Line {ln+1}: balance={single_open} | {line[:100]}')
